const now = new Date();

// Last completed month
const end = new Date(now.getFullYear(), now.getMonth(), 0);

// Start 3 months before end -> total 4 months
const start = new Date(end.getFullYear(), end.getMonth() - 3, 1);

function formatBCBDate(date) {
  return String(date.getDate()).padStart(2, '0') + '/' +
    String(date.getMonth() + 1).padStart(2, '0') + '/' +
    date.getFullYear();
}

const dateInicial = formatBCBDate(start);
const dataFinal = formatBCBDate(end);

const series = [
  // INSS
  { product: "INSS payroll loans", metric: "balance", series: 20578, unit: "BRL_mn" },
  { product: "INSS payroll loans", metric: "nominal_rate_pa", series: 20746, unit: "pct_pa" },
  { product: "INSS payroll loans", metric: "npl90", series: 21118, unit: "pct" },

  // Public payroll
  { product: "Public-sector payroll loans", metric: "balance", series: 20577, unit: "BRL_mn" },
  { product: "Public-sector payroll loans", metric: "nominal_rate_pa", series: 20745, unit: "pct_pa" },
  { product: "Public-sector payroll loans", metric: "npl90", series: 21117, unit: "pct" },

  // CLT / private payroll
  { product: "Private-sector / CLT payroll loans", metric: "balance", series: 20576, unit: "BRL_mn" },
  { product: "Private-sector / CLT payroll loans", metric: "nominal_rate_pa", series: 20744, unit: "pct_pa" },
  { product: "Private-sector / CLT payroll loans", metric: "npl90", series: 21116, unit: "pct" },

  // Vehicle
  { product: "Vehicle financing", metric: "balance", series: 20581, unit: "BRL_mn" },
  { product: "Vehicle financing", metric: "nominal_rate_pa", series: 20749, unit: "pct_pa" },
  { product: "Vehicle financing", metric: "npl90", series: 21121, unit: "pct" },

  // Mortgage
  { product: "Mortgage", metric: "balance", series: 20612, unit: "BRL_mn" },
  { product: "Mortgage", metric: "nominal_rate_pa", series: 20774, unit: "pct_pa" },
  { product: "Mortgage", metric: "npl90", series: 21151, unit: "pct" },

  // Unsecured Personal Loan
  { product: "Unsecured Personal Loans", metric: "balance", series: 29965, unit: "BRL_mn" },
  { product: "Unsecured Personal Loans", metric: "nominal_rate_pa", series: 29974, unit: "pct_pa" },
  { product: "Unsecured Personal Loans", metric: "npl90", series: 29992, unit: "pct" },

  // Overdraft
  { product: "Overdraft", metric: "balance", series: 20573, unit: "BRL_mn" },
  { product: "Overdraft", metric: "nominal_rate_pa", series: 20741, unit: "pct_pa" },
  { product: "Overdraft", metric: "npl90", series: 21113, unit: "pct" }
];

return series.map(s => ({
  json: {
    ...s,
    dateInicial,
    dataFinal
  }
}));

// Robust to both HTTP Request output shapes:
// - "Split Into Items" OFF (default): each item.json is the full array response for one series
// - "Split Into Items" ON: each item.json is a single { data, valor } row, item.pairedItem.item points at the config item

const input = $input.all();
const configItems = $('Build BCB Series Config').all();
const output = [];

function toRow(row, config) {
  let value = Number(String(row.valor).replace(',', '.'));

  // Balance: R$ million -> R$ billion
  if (config.unit === 'BRL_mn') {
    value = value / 1000;
  }

  const [day, month, year] = row.data.split('/');

  return {
    json: {
      reference_month: `${year}-${month}`,
      product: config.product,
      metric: config.metric,
      value: value,
      source: "BCB SGS",
      series: config.series,
      retrieved_at: new Date().toISOString()
    }
  };
}

for (const item of input) {
  const pairedIndex = item.pairedItem?.item ?? 0;
  const config = configItems[pairedIndex].json;

  const body = item.json?.body ?? item.json;

  if (Array.isArray(body)) {
    // Whole-array-in-one-item shape
    for (const row of body) {
      output.push(toRow(row, config));
    }
  } else if (body && typeof body === 'object' && 'data' in body && 'valor' in body) {
    // Split-into-items shape: this item IS one row
    output.push(toRow(body, config));
  }
}

return output;

const items = $input.all();

const grouped = {};

for (const item of items) {
  const r = item.json;

  const key = `${r.reference_month}|${r.product}`;

  if (!grouped[key]) {
    grouped[key] = {
      reference_month: r.reference_month,
      product: r.product,
      balance_brl_bn: null,
      nominal_rate_pa: null,
      npl90: null
    };
  }

  if (r.metric === 'balance') grouped[key].balance_brl_bn = r.value;
  if (r.metric === 'nominal_rate_pa') grouped[key].nominal_rate_pa = r.value;
  if (r.metric === 'npl90') grouped[key].npl90 = r.value;
}

return Object.values(grouped)
  .sort((a, b) =>
    a.reference_month.localeCompare(b.reference_month) ||
    a.product.localeCompare(b.product)
  )
  .map(row => ({ json: row }));

const rows = $input.all();
const complete = [];
const incomplete = [];

for (const item of rows) {
  const r = item.json;

  const isComplete =
    r.balance_brl_bn !== null &&
    r.nominal_rate_pa !== null &&
    r.npl90 !== null;

  if (isComplete) {
    complete.push(item);
  } else {
    incomplete.push({ json: { ...r, status: 'INCOMPLETE' } });
  }
}

if (incomplete.length) {
  console.log('Incomplete rows (not written):', JSON.stringify(incomplete.map(i => i.json)));
}

return complete;
